 * Helper to wrap a Solid function and warn if called with no current Owner.
 */
function patchFn<T extends Function>(fnName: string, originalFn: T): T {
  return ((...args: any[]) => {
    // getOwner returns the current reactive owner if we are in a component/root
    if (!Solid.getOwner?.()) {
      console.warn(`${fnName} called outside a root!`);
      // Show a stack trace so you know **which code** triggered it:
      console.trace();
    }
    return (originalFn as any)(...args);
  }) as unknown as T;
}

/**
 * We mock 'solid-js' so that all imports of 'solid-js' from anywhere
 * in our code will use these patched versions of the functions.
 */
vi.mock('solid-js', async () => {
  // Grab the real 'solid-js' exports to clone them
  const actual = await vi.importActual<any>('solid-js');
  return {
    ...actual,
    // Patch whichever reactivity functions you want to trace:
    createSignal: patchFn('createSignal', actual.createSignal),
    createMemo:   patchFn('createMemo', actual.createMemo),
    createEffect: patchFn('createEffect', actual.createEffect),
    // etc.
  };
});

```

