1. Create or update an example and log out the raw chunks, e.g.

```js
import { openai } from '@ai-sdk/openai';
import { streamText } from 'ai';
import 'dotenv/config';

async function main() {
  const chunks: any[] = [];
  const result = streamText({
    model: openai('gpt-4.1-nano'),
    maxOutputTokens: 1024,
    messages: [{ role: 'user', content: 'Output Y or N.' }],
    providerOptions: {
      openai: {
        logprobs: 5,
      },
    },
    includeRawChunks: true,
    onChunk: ({chunk}) => {
      chunks.push(chunk.rawValue);
    },
  });


  for await (const textPart of result.textStream) {}

  // IMPORTANT: note the `data:` prefix and the `\n\n` suffix!
  console.log(chunks.filter(Boolean).map(c => 'data:' + JSON.stringify(c) + '\n\n'))
}

main().catch(console.error);
```

2. Run the example and copy the output, e.g. `cd examples/ai-core && pnpm tsx src/stream-text/openai.ts | pbcopy`

3. Copy the output of the example run, and use it as value of `chunks` in a `doStream()` test

